using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class WholeUiCleanupTests {
  GameRuntime game;string directory;const string Output="/tmp/idle-whole-ui-review";readonly List<string> issues=new List<string>();int pages;
  [UnitySetUp]public IEnumerator Setup(){Directory.CreateDirectory(Output);directory=Path.Combine(Path.GetTempPath(),"whole-ui-"+Guid.NewGuid());Directory.CreateDirectory(directory);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Tutorial="done";return n;});Prepare();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  void Prepare(){game.Act(s=>{var n=s.Copy();n.Credits=n.Data=ScientificNumber.From(1e20);n.Retention.gems=100000;n.Retention.aiName="AURA";n.Quality=10;n.Efficiency=8;n.Hardware[0]=25;n.Hardware[1]=10;n.Hardware[2]=2;n.Prestige.resets=1;n.Prestige.Total=n.Prestige.Free=n.Prestige.Cycle=n.Prestige.Entitlement=ScientificNumber.From(1e7);n.Prestige.known=PrestigeBalance.Nodes.Select(d=>d.Id).ToArray();n.Workshop.nodes=(string[])n.Prestige.known.Clone();n.Prestige.lab=n.Prestige.labSeed=true;n.Meta.resets=1;n.Meta.models=Enumerable.Repeat(0,MetaBalance.Models.Length).ToArray();n.Meta.available=n.Meta.total=ScientificNumber.From(10000).ToData();n.Meta.axioms=Enumerable.Repeat(1,MetaBalance.Axioms.Length).ToArray();n.Prestige.knowledge=ScientificNumber.From(10000).ToData();for(int i=0;i<n.Research.Length;i++)n.Research[i]=Balance.Research[i].Project?1:4;n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.knownBlueprints=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.components=Enumerable.Repeat(100000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.fragments=1000;n.Workshop.inventory=ItemBalance.Items.Select((d,i)=>new ItemInstance{id="audit-item-"+i,type=d.Id,level=12,rarity=i%6}).ToArray();var used=new List<string>();for(int slot=0;slot<6;slot++){string family=ItemBalance.Slots[slot].Replace("Aux","");var item=n.Workshop.inventory.First(i=>Workshop.Definition(i).Family==family&&!used.Contains(i.id));n=Workshop.Equip(n,item.id,ItemBalance.Slots[slot]);used.Add(item.id);}return MetaRules.Select(n,"K01");});game.Act(s=>{var n=s.Copy();n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";return n;});game.Act(s=>Game.Research(s,"dataGeneration"));Assert.That(game.State.Story.open,Is.Null,"Prepared views must not accidentally resume the name introduction");}

  IEnumerator Inspect(string name,string language,int width,Transform surface=null){yield return null;yield return null;game.FlushLocalization();Canvas.ForceUpdateCanvases();yield return null;Canvas.ForceUpdateCanvases();Assert.That(game.Writable,Is.True,game.Status.text);var viewport=surface==null?game.Content.GetComponentInParent<ScrollRect>().viewport:(RectTransform)game.Content.GetComponentInParent<Canvas>().rootCanvas.transform;
   foreach(var rect in (surface??game.Content).GetComponentsInChildren<RectTransform>()){
    if(surface==null&&rect.GetComponentInParent<PrestigeNetworkView>()!=null)continue;
    var button=rect.GetComponent<Button>();var text=rect.GetComponent<Text>();if(button==null&&text==null)continue;
    var corners=new Vector3[4];rect.GetWorldCorners(corners);float left=viewport.InverseTransformPoint(corners[0]).x,right=viewport.InverseTransformPoint(corners[2]).x;
    if(left<viewport.rect.xMin-1||right>viewport.rect.xMax+1)issues.Add(language+"/"+width+"/"+name+"/"+rect.name+" outside "+left+".."+right+" viewport "+viewport.rect);
    if(button!=null&&button.interactable&&(rect.rect.width<43.5f||rect.rect.height<43.5f))issues.Add(language+"/"+width+"/"+name+"/"+rect.name+" small "+rect.rect.size);
   }
   if(width==(language=="de"?320:390)){WorkshopTests.Capture(width,Screen.height,Output+"/"+name+"-"+language+"-"+width+".png");var scroll=surface==null?game.Content.GetComponentInParent<ScrollRect>():surface.GetComponentInChildren<ScrollRect>();if(scroll!=null)scroll.verticalNormalizedPosition=0;yield return null;WorkshopTests.Capture(width,Screen.height,Output+"/"+name+"-bottom-"+language+"-"+width+".png");if(scroll!=null)scroll.verticalNormalizedPosition=1;}
   pages++;
  }
  [UnityTest]public IEnumerator AllPagesAndTheirNavigationFitSmallPhones(){
   foreach(string language in new[]{"de","en"})foreach(int width in new[]{320,390,430}){
    game.Act(s=>SettingsRules.Change(s,"language",language));PortraitGameView.Set(width,width==320?568:width==390?846:932);yield return null;
    foreach(string route in new[]{"training","research","models","prestige","production","shop","market","gems","store","ads","missions","seasons","profile","company","progress","story","settings","storage","goals","challenges"}){game.Show(route);yield return Inspect(route,language,width);}
    game.Show("items");foreach(string mode in new[]{"inventory","components","blueprints","craft","fusion"}){game.WorkshopView.ChangeMode(mode);yield return Inspect("forge-"+mode,language,width);}
    game.Show("profile");foreach(string nav in new[]{"ShowBadges","ShowAchievements","ShowOnboarding","ShowStaticChallenges","ShowProfile"}){GameObject.Find(nav).GetComponent<Button>().onClick.Invoke();yield return Inspect(nav,language,width);}
    GameObject.Find("ProfileEdit").GetComponent<Button>().onClick.Invoke();yield return Inspect("profile-edit",language,width);GameObject.Find("ProfileMailbox").GetComponent<Button>().onClick.Invoke();yield return Inspect("profile-mailbox",language,width);
    game.Show("gems");foreach(string nav in new[]{"permanent","time","materials","capsule"}){GameObject.Find("GemPage-"+nav).GetComponent<Button>().onClick.Invoke();yield return Inspect("gems-"+nav,language,width);}
    game.Show("research");foreach(int area in new[]{0,1,2,3,4}){game.SetResearchArea(area);yield return Inspect("research-area-"+area,language,width);}
    for(int i=0;i<3;i++){game.ShowDetails("training",i);yield return Inspect("training-detail-"+i,language,width);}game.ShowDetails("research",0);yield return Inspect("research-detail",language,width);
    game.Show("models");yield return null;GameObject.Find("ModelDetails-K10").GetComponent<Button>().onClick.Invoke();yield return Inspect("model-expanded",language,width);
    game.Show("production");foreach(string kind in new[]{"compute","users","credits","data"}){GameObject.Find("ProductionSources-"+kind).GetComponent<Button>().onClick.Invoke();yield return Inspect("production-"+kind,language,width);}GameObject.Find("ProductionHardware").GetComponent<Button>().onClick.Invoke();yield return Inspect("production-hardware",language,width);
    game.Show("progress");yield return null;GameObject.Find("ShowLifetimeDetails").GetComponent<Button>().onClick.Invoke();GameObject.Find("ShowHardwareMastery").GetComponent<Button>().onClick.Invoke();yield return Inspect("progress-details",language,width);
    game.Show("missions");foreach(int period in new[]{0,1,2}){GameObject.Find("MissionPeriod-"+period).GetComponent<Button>().onClick.Invoke();yield return Inspect("missions-"+period,language,width);}
    game.Show("seasons");foreach(int track in new[]{0,1}){GameObject.Find("SeasonTrack-"+track).GetComponent<Button>().onClick.Invoke();yield return Inspect("season-track-"+track,language,width);}GameObject.Find("SeasonBand-4").GetComponent<Button>().onClick.Invoke();yield return Inspect("season-last-band",language,width);GameObject.Find("SeasonCollectionAccess").GetComponent<Button>().onClick.Invoke();yield return Inspect("season-collection",language,width);
    game.Show("company");foreach(string name in new[]{"CompanySearch","CompanyVouchers","CompanyInvites","CompanyGoods","CompanyPrivacy"}){GameObject.Find(name).GetComponent<Button>().onClick.Invoke();yield return Inspect(name,language,width);}
    game.Show("challenges");GameObject.Find("ChallengeDetails").GetComponent<Button>().onClick.Invoke();yield return Inspect("challenge-rules",language,width);
    game.Show("profile");yield return null;GameObject.Find("ShowNameLicenses").GetComponent<Button>().onClick.Invoke();yield return Inspect("profile-licenses",language,width);
    game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return null;game.WorkshopView.OpenItem("audit-item-0");yield return Inspect("item-details",language,width,game.WorkshopView.DetailRoot.transform);game.WorkshopView.CloseDetail();game.WorkshopView.OpenComponent(0);yield return Inspect("component-details",language,width,game.WorkshopView.DetailRoot.transform);game.WorkshopView.CloseDetail();game.WorkshopView.ChangeMode("blueprints");yield return null;GameObject.Find("recipe-quantum-chip").GetComponent<Button>().onClick.Invoke();yield return Inspect("blueprint-details",language,width,game.WorkshopView.DetailRoot.transform);game.WorkshopView.CloseDetail();
    game.Show("settings");yield return null;GameObject.Find("RequestCampaignReset").GetComponent<Button>().onClick.Invoke();yield return Inspect("settings-reset-confirmation",language,width);GameObject.Find("CancelCampaignReset").GetComponent<Button>().onClick.Invoke();
    game.Show("storage");foreach(string name in new[]{"StorageRecovery","StorageReturns","StorageDiagnostics","OpenPlatformCloud"}){GameObject.Find(name).GetComponent<Button>().onClick.Invoke();yield return Inspect(name,language,width);}
    game.Show("company");yield return null;GameObject.Find("CompanyPrivacy").GetComponent<Button>().onClick.Invoke();yield return null;GameObject.Find("DeleteOnlineAccount").GetComponent<Button>().onClick.Invoke();yield return Inspect("account-deletion-confirmation",language,width);GameObject.Find("CancelAccountDeletion").GetComponent<Button>().onClick.Invoke();
    game.Show("market");yield return null;GameObject.Find("MarketOffer-chest:common").GetComponent<Button>().onClick.Invoke();yield return null;yield return Inspect("shop-purchase-confirmation",language,width,GameObject.Find("ShopPurchaseConfirm").transform);GameObject.Find("PurchaseCancel").GetComponent<Button>().onClick.Invoke();yield return null;GameObject.Find("MarketOffer-chest:common").transform.Find("ChestInformation").GetComponent<Button>().onClick.Invoke();yield return null;var chestInfo=GameObject.Find("MarketInformation");yield return Inspect("chest-information",language,width,chestInfo.transform);chestInfo.transform.Find("DetailPanel/CloseItemDetail").GetComponent<Button>().onClick.Invoke();
    game.Show("gems");yield return null;GameObject.Find("GemPage-capsule").GetComponent<Button>().onClick.Invoke();yield return null;GameObject.Find("CapsuleInfo").GetComponent<Button>().onClick.Invoke();yield return null;var odds=GameObject.Find("CapsuleInformation");yield return Inspect("capsule-information",language,width,odds.transform);GameObject.Find("ShowCapsuleItemOdds").GetComponent<Button>().onClick.Invoke();yield return Inspect("capsule-item-odds",language,width,odds.transform);odds.transform.Find("DetailPanel/CloseItemDetail").GetComponent<Button>().onClick.Invoke();
    game.Show("prestige");yield return null;game.PrestigeView.OpenNode("W07");yield return Inspect("int-node-detail",language,width,GameObject.Find("INTDetails").transform);game.PrestigeView.Cancel();game.PrestigeView.SetLayer(true);yield return Inspect("axioms",language,width);game.PrestigeView.OpenNode("D06");yield return Inspect("axiom-detail",language,width,GameObject.Find("INTDetails").transform);game.PrestigeView.Cancel();
    game.Show("hardware");game.GetComponent<GameMenu>().Open();yield return null;yield return null;WorkshopTests.Capture(width,Screen.height,Output+"/menu-"+language+"-"+width+".png");game.GetComponent<GameMenu>().Close();
   }
   File.WriteAllLines(Output+"/issues.txt",issues.Distinct());File.WriteAllText(Output+"/pages.txt",pages.ToString());Assert.That(issues.Distinct(),Is.Empty,string.Join("\n",issues.Distinct().Take(30)));
  }
 }
}
